import math

def evaluate_expression(a):
    """Calculates a * floor(22*a*floor(22*a*floor(22*a)))"""
    if a <= 0:
        # Since the target is 4, we only need to check positive a.
        # If a=0, result is 0.
        return 0.0

    # Inner term: floor(22*a)
    T2 = math.floor(22 * a)

    # Third term: floor(22*a * T2)
    T4 = math.floor(22 * a * T2)

    # Fifth term: floor(22*a * T4)
    T6 = math.floor(22 * a * T4)

    # Final result: a * T6
    return a * T6

# --- Expanded Test Values ---
test_values = set()

# 1. Test a = 4/N for N from 10 to 40
for N in range(10, 41):
    test_values.add(4/N)

# 2. Fine grid search near 1/22 (0.04545...)
for i in range(1, 51):
    test_values.add(1/22 + i/1000)
    test_values.add(1/22 - i/1000)

# 3. Fine grid search near 1/12 (0.08333...)
for i in range(1, 51):
    test_values.add(1/12 + i/1000)
    test_values.add(1/12 - i/1000)

test_list = sorted(list(test_values))

results = {}
for a in test_list:
    try:
        result = evaluate_expression(a)
        results[a] = result
    except OverflowError:
        results[a] = "Overflow"

# Check which results are numerically close to 4
candidates = {a: result for a, result in results.items() if abs(result - 4) < 1e-9}

# Also check the original simple values for completeness
original_simple = [1/22, 1/12]
for a in original_simple:
    result = evaluate_expression(a)
    if abs(result - 4) < 1e-9:
        candidates[a] = result

print("--- Candidates for a such that E(a) = 4 ---")
if candidates:
    for a, result in candidates.items():
        print(f"Candidate a = {a} (exact form or float): Result = {result}")
else:
    print("No candidates found in the tested set close to 4.")
